import java.util.Random;

public class Bench {
    // pure merge sort: recurse to single elements (no insertion cutoff)
    static void pureSort(int[] a, int[] buf, int lo, int hi) {
        if (lo >= hi) return;
        int mid = lo + (hi - lo) / 2;
        pureSort(a, buf, lo, mid);
        pureSort(a, buf, mid + 1, hi);
        System.arraycopy(a, lo, buf, lo, hi - lo + 1);
        int l = lo, r = mid + 1;
        for (int d = lo; d <= hi; d++) {
            if (l > mid) a[d] = buf[r++];
            else if (r > hi) a[d] = buf[l++];
            else if (buf[l] <= buf[r]) a[d] = buf[l++];
            else a[d] = buf[r++];
        }
    }
    static void pure(int[] a) { if (a != null && a.length > 1) pureSort(a, new int[a.length], 0, a.length - 1); }

    static long time(Runnable r, int reps) {
        long best = Long.MAX_VALUE;
        for (int i = 0; i < reps; i++) {
            long t = System.nanoTime(); r.run(); best = Math.min(best, System.nanoTime() - t);
        }
        return best;
    }

    public static void main(String[] x) {
        int n = 2_000_000, trials = 8;
        Random rnd = new Random(7);
        int[] base = new int[n];
        for (int i = 0; i < n; i++) base[i] = rnd.nextInt();
        // warmup
        for (int w = 0; w < 5; w++) { int[] c = base.clone(); MergeSort.sort(c); int[] d = base.clone(); pure(d); }
        long withCutoff = time(() -> { int[] c = base.clone(); MergeSort.sort(c); }, trials);
        long pureT      = time(() -> { int[] c = base.clone(); pure(c); }, trials);
        System.out.printf("n=%d (best of %d)%n", n, trials);
        System.out.printf("  pure merge sort      : %6.1f ms%n", pureT / 1e6);
        System.out.printf("  with insertion cutoff: %6.1f ms%n", withCutoff / 1e6);
        System.out.printf("  speedup              : %.2fx%n", (double) pureT / withCutoff);
    }
}
